package com.clavis.reader;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded disk PCM cache lets the next chapter finish converting ahead of playback. */
final class NarrationAudio {
 static File file(Context c,String text,int start,int end,float speed,int speaker)throws Exception{String input="kitten-original-prosody-v12:"+speaker+":"+speed+":"+text.substring(start,end);byte[] digest=MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));StringBuilder key=new StringBuilder();for(byte b:digest)key.append(String.format(Locale.US,"%02x",b&255));File dir=new File(c.getCacheDir(),"listen-audio-v12");dir.mkdirs();return new File(dir,key+".pcm");}
 static short[] read(File file,int rate){if(!file.isFile())return null;try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(file)))){if(in.readInt()!=0x434c4156||in.readInt()!=rate)return null;int count=in.readInt();if(count<1||count>8000000||file.length()!=12L+count*2L)return null;short[] samples=new short[count];for(int n=0;n<count;n++)samples[n]=in.readShort();file.setLastModified(System.currentTimeMillis());return samples;}catch(Exception e){file.delete();return null;}}
 static void write(File file,int rate,short[] samples)throws Exception{AtomicFile atomic=new AtomicFile(file);FileOutputStream raw=atomic.startWrite();try{DataOutputStream out=new DataOutputStream(new BufferedOutputStream(raw));out.writeInt(0x434c4156);out.writeInt(rate);out.writeInt(samples.length);for(short sample:samples)out.writeShort(sample);out.flush();atomic.finishWrite(raw);}catch(Exception e){atomic.failWrite(raw);throw e;}File[] files=file.getParentFile().listFiles(f->f.getName().endsWith(".pcm"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long total=0;for(File f:files)total+=f.length();for(File f:files){if(total<=256L*1024*1024)break;if(!f.equals(file)&&f.delete())total-=f.length();}}
}
